using TownOfHost;using TownOfHost.Roles.Core;using TownOfHost.Roles.Neutral;using TownOfHost.Roles.Madmate;
partial class Program {
static int passed;static uint net;static void Check(bool b){if(!b)throw new Exception("assertion failed");}static void Test(string s,Action a){Setup();a();passed++;Console.WriteLine("PASS "+s);}
static PlayerControl P(byte id,CustomRoles role=CustomRoles.Crewmate)=>new(){PlayerId=id,NetId=++net,Role=role};
static Eliminator R(byte id=1)=>new(P(id,CustomRoles.Eliminator));
static void Info(CustomRoles r,CustomRoleTypes t)=>CustomRoleManager.AllRolesInfo[r]=new(){RoleName=r,CustomRoleType=t};
static void Setup(){CustomRoleManager.AllActiveRoles.Clear();CustomRoleManager.AllRolesInfo.Clear();OptionItem.All.Clear();CustomRoleManager.Forced=0;CustomRoleManager.Reenter=CustomRoleManager.Throw=false;AmongUsClient.Instance.AmHost=true;MadBetrayer.Mad=true;GameStates.InGame=GameStates.IsInTask=true;GameStates.Intro=GameStates.IsMeeting=GameStates.CalledMeeting=GameStates.IsOutro=false;CustomWinnerHolder.WinnerTeam=CustomWinner.Default;CustomWinnerHolder.WinnerIds.Clear();CustomWinnerHolder.WinnerRoles.Clear();CustomWinnerHolder.NeutralWinnerIds.Clear();CustomWinnerHolder.CantWinPlayerIds.Clear();CustomWinnerHolder.AdditionalWinnerRoles.Clear();Eliminator.Reset();var info=Eliminator.RoleInfo;CustomRoleManager.AllRolesInfo[info.RoleName]=info;info.Setup();foreach(var r in new[]{CustomRoles.Crewmate,CustomRoles.Engineer,CustomRoles.Sheriff})Info(r,CustomRoleTypes.Crewmate);foreach(var r in new[]{CustomRoles.Impostor,CustomRoles.Nova})Info(r,CustomRoleTypes.Impostor);foreach(var r in new[]{CustomRoles.Madmate,CustomRoles.MadKind})Info(r,CustomRoleTypes.Madmate);foreach(var r in new[]{CustomRoles.Jackal,CustomRoles.LessThan,CustomRoles.Jester,CustomRoles.God,CustomRoles.Fox})Info(r,CustomRoleTypes.Neutral);}
static MurderInfo Attempt(Eliminator r,PlayerControl target,bool guard=false,bool protectedByVanilla=false){var i=new MurderInfo(r.Player,target){GuardPower=guard?1:0};r.OnCheckMurderAsKiller(i);if(i.DoKill&&i.CanKill&&i.KillPower>i.GuardPower&&!protectedByVanilla){target.Data.IsDead=true;r.OnMurderPlayerAsKiller(i);}return i;}
static void Kills(Eliminator r,int n){for(int k=0;k<n;k++)Attempt(r,P((byte)(20+k)));}
static bool Win(Eliminator r,CustomWinner team){CustomWinnerHolder.WinnerTeam=team;Eliminator.ApplyAdditionalWinners();return CustomWinnerHolder.WinnerIds.Contains(r.Player.PlayerId);}
static void Main(){
Test("stable role ID and config ID",()=>Check((int)CustomRoles.Eliminator==382&&Eliminator.RoleInfo.ConfigId==993000));
Test("registered neutral uses vanilla impostor and desync",()=>{var i=Eliminator.RoleInfo;Check(i.CustomRoleType==CustomRoleTypes.Neutral&&i.Base()==AmongUs.GameOptions.RoleTypes.Impostor&&i.Desync&&i.IsNewRole&&i.From==From.TownOfHost_Shell);});
Test("presentation order places the new role before Nova",()=>Check(Hamo435RoleOrder.Priority[CustomRoles.Eliminator]<Hamo435RoleOrder.Priority[CustomRoles.Nova]));
Test("exactly three ability options with stable IDs",()=>Check(OptionItem.All.Keys.OrderBy(x=>x).SequenceEqual(new[]{993010,993011,993012})));
Test("kill cooldown range step default and units",()=>{var o=OptionItem.All[993010];var r=(ClampedFloatValueRule)o.Rule;Check(r.Min==2.5f&&r.Max==100&&r.Step==2.5f&&o.Value==30&&o.Format==OptionFormat.Seconds);});
Test("required kill range step default and units",()=>{var o=OptionItem.All[993011];var r=(ClampedIntegerValueRule)o.Rule;Check(r.Min==1&&r.Max==15&&r.Step==1&&o.Value==2&&o.Format==OptionFormat.Players);});
Test("survival defaults OFF",()=>Check(!OptionItem.All[993012].GetBool()));
Test("kill cooldown uses configured value",()=>{var r=R();OptionItem.All[993010].Value=62.5f;Check(r.CalculateKillCooldown()==62.5f);});
Test("vent and sabotage are disabled",()=>{var r=R();Check(!r.CanUseImpostorVentButton()&&!r.CanUseSabotageButton());});
foreach(var targetRole in new[]{CustomRoles.Crewmate,CustomRoles.Engineer,CustomRoles.Sheriff})Test("custom crew target is killed: "+targetRole,()=>{var r=R();var p=P(2,targetRole);Attempt(r,p);Check(p.Data.IsDead&&!r.Player.Data.IsDead&&r.SuccessfulCrewKills==1);});
foreach(var targetRole in new[]{CustomRoles.Impostor,CustomRoles.Nova,CustomRoles.Jackal,CustomRoles.LessThan,CustomRoles.Madmate,CustomRoles.MadKind})Test("non-crew target survives and shooter dies: "+targetRole,()=>{var r=R();var p=P(2,targetRole);var i=Attempt(r,p);Check(!p.Data.IsDead&&r.Player.Data.IsDead&&r.SuccessfulCrewKills==0&&!i.DoKill&&CustomRoleManager.Forced==1);});
foreach(var addon in new[]{CustomRoles.SKMadmate,CustomRoles.Jackaldoll,CustomRoles.Tama,CustomRoles.Amanojaku,CustomRoles.Lovers,CustomRoles.RedLovers,CustomRoles.OneLove,CustomRoles.Faction,CustomRoles.Twins,CustomRoles.Triplets})Test("crew base with faction-changing subrole is not crew: "+addon,()=>{var r=R();var p=P(2);p.Subroles.Add(addon);Attempt(r,p);Check(!p.Data.IsDead&&r.Player.Data.IsDead&&r.SuccessfulCrewKills==0);});
foreach(bool mad in new[]{true,false})Test("MadBetrayer custom faction is rejected in either mode: "+mad,()=>{MadBetrayer.Mad=mad;var r=R();var p=P(2,CustomRoles.MadBetrayer);Attempt(r,p);Check(!p.Data.IsDead&&r.Player.Data.IsDead);});
Test("a shield rejects the kill without incrementing count",()=>{var r=R();var p=P(2);Attempt(r,p,guard:true);Check(!p.Data.IsDead&&!r.Player.Data.IsDead&&r.SuccessfulCrewKills==0);});
Test("late vanilla protection does not increment count",()=>{var r=R();var p=P(2);Attempt(r,p,protectedByVanilla:true);Check(!p.Data.IsDead&&r.SuccessfulCrewKills==0);});
Test("failure flags prevent counting even if a callback is received",()=>{var r=R();var p=P(2);var i=new MurderInfo(r.Player,p);r.OnCheckMurderAsKiller(i);i.CanKill=false;p.Data.IsDead=true;r.OnMurderPlayerAsKiller(i);Check(r.SuccessfulCrewKills==0);});
Test("target callback cancellation prevents counting",()=>{var r=R();var p=P(2);var i=new MurderInfo(r.Player,p){DoKill=false};r.OnCheckMurderAsKiller(i);p.Data.IsDead=true;r.OnMurderPlayerAsKiller(i);Check(r.SuccessfulCrewKills==0);});
Test("duplicate murder callback counts once",()=>{var r=R();var i=Attempt(r,P(2));for(int n=0;n<20;n++)r.OnMurderPlayerAsKiller(i);Check(r.SuccessfulCrewKills==1);});
Test("unsolicited or reconstructed callback does not count",()=>{var r=R();var p=P(2);p.Data.IsDead=true;r.OnMurderPlayerAsKiller(new(r.Player,p));Check(r.SuccessfulCrewKills==0);});
Test("redirected murder victim is not credited as the original target",()=>{var r=R();var p=P(2);var i=new MurderInfo(r.Player,p);r.OnCheckMurderAsKiller(i);i.AppearanceTarget=P(3);p.Data.IsDead=true;r.OnMurderPlayerAsKiller(i);Check(r.SuccessfulCrewKills==0);});
Test("pending victim network identity cannot be swapped",()=>{var r=R();var p=P(2);var i=new MurderInfo(r.Player,p);r.OnCheckMurderAsKiller(i);p.NetId++;p.Data.IsDead=true;r.OnMurderPlayerAsKiller(i);Check(r.SuccessfulCrewKills==0);});
Test("successful resurrection and second kill are distinct successes",()=>{var r=R();var p=P(2);Attempt(r,p);p.Data.IsDead=false;Attempt(r,p);Check(r.SuccessfulCrewKills==2);});
Test("nested self murder cannot recursively kill the original target",()=>{CustomRoleManager.Reenter=true;var r=R();var p=P(2,CustomRoles.Impostor);Attempt(r,p);Check(CustomRoleManager.Forced==1&&!p.Data.IsDead&&r.Player.Data.IsDead&&r.SuccessfulCrewKills==0);});
Test("a failed forced self murder leaves the original target cancelled",()=>{CustomRoleManager.Throw=true;var r=R();var p=P(2,CustomRoles.Jackal);var i=new MurderInfo(r.Player,p);try{r.OnCheckMurderAsKiller(i);}catch(InvalidOperationException){}Check(!i.DoKill&&!p.Data.IsDead);CustomRoleManager.Throw=false;Attempt(r,P(3));Check(r.SuccessfulCrewKills==1);});
Test("client cannot authorize a kill or suicide",()=>{var r=R();AmongUsClient.Instance.AmHost=false;var p=P(2,CustomRoles.Impostor);Attempt(r,p);Check(!p.Data.IsDead&&!r.Player.Data.IsDead&&CustomRoleManager.Forced==0);});
Test("client cannot record or add winners",()=>{var r=R();Kills(r,2);AmongUsClient.Instance.AmHost=false;Check(!Win(r,CustomWinner.Impostor));});
foreach(var state in new[]{"meeting","intro","called","outro","notTask","notGame","dead","disconnected","disposed"})Test("inactive shooter cannot act: "+state,()=>{var r=R();switch(state){case "meeting":GameStates.IsMeeting=true;break;case "intro":GameStates.Intro=true;break;case "called":GameStates.CalledMeeting=true;break;case "outro":GameStates.IsOutro=true;break;case "notTask":GameStates.IsInTask=false;break;case "notGame":GameStates.InGame=false;break;case "dead":r.Player.Data.IsDead=true;break;case "disconnected":r.Player.Data.Disconnected=true;break;default:r.OnDestroy();break;}var p=P(2);Attempt(r,p);Check(!p.Data.IsDead&&r.SuccessfulCrewKills==0);});
foreach(var state in new[]{"dead","disconnected","dummy","unreal","testbot","gm","nullData"})Test("invalid target is ignored safely: "+state,()=>{var r=R();var p=P(2);switch(state){case "dead":p.Data.IsDead=true;break;case "disconnected":p.Data.Disconnected=true;break;case "dummy":p.isDummy=true;break;case "unreal":p.notRealPlayer=true;break;case "testbot":p.TestBot=true;break;case "gm":p.Role=CustomRoles.GM;break;default:p.Data=null;break;}var i=new MurderInfo(r.Player,p);r.OnCheckMurderAsKiller(i);Check(!i.DoKill&&CustomRoleManager.Forced==0&&r.SuccessfulCrewKills==0);});
Test("ordinary early winner pass cannot add a provisional winner",()=>{var r=R();Kills(r,2);CustomWinnerHolder.WinnerTeam=CustomWinner.Impostor;var role=CustomRoles.Eliminator;Check(!r.CheckWin(ref role));});
foreach(var team in new[]{CustomWinner.Impostor,CustomWinner.Jackal,CustomWinner.LessThan,CustomWinner.Jester,CustomWinner.God,CustomWinner.Lovers})Test("sufficient kills add a winner for final faction: "+team,()=>{var r=R();Kills(r,2);CustomWinnerHolder.WinnerIds.Add(9);CustomWinnerHolder.AdditionalWinnerRoles.Add(CustomRoles.Opportunist);Check(Win(r,team));Check(CustomWinnerHolder.WinnerTeam==team&&CustomWinnerHolder.WinnerIds.Contains(9)&&CustomWinnerHolder.AdditionalWinnerRoles.Contains(CustomRoles.Opportunist)&&CustomWinnerHolder.AdditionalWinnerRoles.Contains(CustomRoles.Eliminator)&&!CustomWinnerHolder.WinnerRoles.Contains(CustomRoles.Eliminator));});
foreach(var team in new[]{CustomWinner.Crewmate,CustomWinner.None,CustomWinner.Draw,CustomWinner.Default,CustomWinner.SuddenDeathRed,(CustomWinner)999999})Test("special or crew ending does not add a winner: "+team,()=>{var r=R();Kills(r,2);Check(!Win(r,team));});
Test("too few kills cannot win",()=>{var r=R();Kills(r,1);Check(!Win(r,CustomWinner.Impostor));});
for(int required=1;required<=15;required++){int n=required;Test("required-kill threshold "+n,()=>{OptionItem.All[993011].Value=n;var r=R();Kills(r,n-1);Check(!Win(r,CustomWinner.Impostor));CustomWinnerHolder.WinnerTeam=CustomWinner.Default;Kills(r,1);Check(Win(r,CustomWinner.Impostor));});}
foreach(bool survive in new[]{false,true})foreach(bool alive in new[]{false,true})Test("survival rule ON="+survive+", alive="+alive,()=>{OptionItem.All[993012].Value=survive?1:0;var r=R();Kills(r,2);r.Player.Data.IsDead=!alive;Check(Win(r,CustomWinner.Impostor)==(!survive||alive));});
Test("multiple owners keep counters and eligibility separate",()=>{var a=R(1);var b=R(2);Kills(a,2);Kills(b,1);CustomWinnerHolder.WinnerTeam=CustomWinner.Impostor;Eliminator.ApplyAdditionalWinners();Check(CustomWinnerHolder.WinnerIds.SetEquals(new byte[]{1})&&a.SuccessfulCrewKills==2&&b.SuccessfulCrewKills==1);});
Test("multiple eligible owners each receive an additional win",()=>{var a=R(1);var b=R(2);Kills(a,2);Kills(b,2);CustomWinnerHolder.WinnerTeam=CustomWinner.Impostor;Eliminator.ApplyAdditionalWinners();Eliminator.ApplyAdditionalWinners();Check(CustomWinnerHolder.WinnerIds.SetEquals(new byte[]{1,2})&&CustomWinnerHolder.AdditionalWinnerRoles.Count==1);});
Test("explicit game-wide loss restrictions are preserved",()=>{var r=R();Kills(r,2);CustomWinnerHolder.CantWinPlayerIds.Add(1);Check(!Win(r,CustomWinner.Impostor));});
Test("disconnected players do not gain a new win",()=>{var r=R();Kills(r,2);r.Player.Data.Disconnected=true;Check(!Win(r,CustomWinner.Impostor));});
Test("meeting keeps cumulative kills but invalidates pending requests",()=>{var r=R();Kills(r,1);var p=P(3);var i=new MurderInfo(r.Player,p);r.OnCheckMurderAsKiller(i);r.OnStartMeeting();p.Data.IsDead=true;r.OnMurderPlayerAsKiller(i);Check(r.SuccessfulCrewKills==1);});
Test("end round clears old counts and closes the old instance",()=>{var r=R();Kills(r,2);Check(Win(r,CustomWinner.Impostor));Eliminator.EndRound();Check(r.SuccessfulCrewKills==0&&!r.CanUseKillButton());CustomWinnerHolder.WinnerIds.Clear();Eliminator.ApplyAdditionalWinners();Check(CustomWinnerHolder.WinnerIds.Count==0);});
Test("role replacement cannot inherit a counter",()=>{var old=R();Kills(old,2);old.OnDestroy();var fresh=R();Check(fresh.SuccessfulCrewKills==0&&!Win(fresh,CustomWinner.Impostor));});
Test("reset removes prior-round success counts",()=>{var r=R();Kills(r,2);Eliminator.Reset();Check(r.SuccessfulCrewKills==0&&!Win(r,CustomWinner.Impostor));});
Test("vanilla targets use the same host-authoritative kill path",()=>{var r=R();var target=P(2);target.Vanilla=true;Attempt(r,target);Check(target.Data.IsDead&&r.SuccessfulCrewKills==1);});
Test("the final faction after takeover controls eligibility",()=>{var r=R();Kills(r,2);CustomWinnerHolder.WinnerTeam=CustomWinner.Crewmate;CustomWinnerHolder.WinnerTeam=CustomWinner.Jackal;Eliminator.ApplyAdditionalWinners();Check(CustomWinnerHolder.WinnerIds.Contains(1));});
CompatibilityTests();
Console.WriteLine($"RESULT {passed} passed, 0 failed (actual role and extracted faction helpers; Unity/network/game-state substitutes)");}
}
